def levenshtein(a, b):
    m = len(a)
    n = len(b)
    dp = np.empty((m+1, n+1), dtype=int)
    for i in range(m+1):
        for j in range(n+1):
            dp[i, j] = 0
    for i in range(m+1):
        dp[i, 0] = i
    for j in range(n+1):
        dp[0, j] = j
    for i in range(1, m+1):
        for j in range(1, n+1):
            if a[i-1] == b[j-1]:
                cost = 0
            else:
                cost = 1
            dp[i, j] = min(dp[i-1, j] + 1,dp[i, j-1] + 1,dp[i-1, j-1] + cost)

    return dp[m, n]

