def sac_a_dos(poids, valeurs, n, W):
    dp = np.empty(W+1, dtype=int)

    for w in range(W+1):
      dp[w] = 0

    for i in range(n):
      for w in range(W, poids[i]-1, -1):
        dp[w] = max(dp[w], dp[w - poids[i]] + valeurs[i])

    return dp[W]

