def recherche_dichotomique(t, val, debut, fin):
    """
    Recherche dichotomique (binaire) dans le sous-tableau t[debut:fin+1]
    Retourne l'indice de val si trouvé, sinon -1
    """
    while debut <= fin:
        mil = (debut + fin) // 2
        if t[mil] == val:
            return mil
        elif t[mil] < val:
            debut = mil + 1
        else:
            fin = mil - 1
    return -1

def recherche_exponentielle(t, val, n):
    """
    Recherche exponentielle dans un tableau trié t de taille n
    Retourne l'indice de val si trouvé, sinon -1
    """

    # Vérification du premier élément
    if t[0] == val:
        return 0

    # Boucle exponentielle pour trouver l'intervalle
    i = 1
    while i < n and t[i] <= val:
        i = i * 2

    # Recherche dichotomique dans l'intervalle trouvé
    debut = i // 2
    fin = min(i, n - 1)
    return recherche_dichotomique(t, val, debut, fin)

import numpy as np

def interpolation_search(t, val, n):
    lo = 0
    hi = n - 1   

    while lo <= hi and t[lo] <= val <= t[hi]:
        if lo == hi:
            return lo if t[lo] == val else -1

        # Calcul de la position estimée
        pos = lo + ((val - t[lo]) * (hi - lo)) // (t[hi] - t[lo])

        if t[pos] == val:
            return pos
        elif t[pos] < val:
            lo = pos + 1
        else:
            hi = pos - 1

    return -1
