def recherche_binaire(T, val, g, d):
    if g > d:
        return False
    m = (g + d) // 2
    if T[m] == val:
        return True
    elif T[m] > val:
        return recherche_binaire(T, val, g, m-1)
    else:
        return recherche_binaire(T, val, m+1, d)

